tool_input.command:
cd "$(pwd)" && python3 -c "
import databricks.sdk
w = databricks.sdk.WorkspaceClient()
# Check schema exists
try:
    s = w.schemas.get('workspace.mlpab600b4f')
    print('schema:', s.full_name)
except Exception as e:
    print('schema err:', e)
# List volumes in schema
try:
    for v in w.volumes.list('workspace','mlpab600b4f'):
        print('volume:', v.full_name)
except Exception as e:
    print('vol list err:', e)
# Existing tables
try:
    for t in w.tables.list('workspace','mlpab600b4f'):
        print('table:', t.full_name)
except Exception as e:
    print('tbl err:', e)
" 2>&1 | head -40

cd "$(pwd)" && python3 -c "
import databricks.sdk
w = databricks.sdk.WorkspaceClient()
print('=== Tables ===')
for t in w.tables.list('workspace','mlpab600b4f'):
    print(t.name, t.table_type)
print('=== Registered models ===')
try:
    for m in w.registered_models.list(catalog_name='workspace', schema_name='mlpab600b4f'):
        print(m.full_name)
except Exception as e: print('rm err',e)
print('=== Online tables ===')
try:
    ot=w.online_tables.get('workspace.mlpab600b4f.airqpred0ecd46_online')
    print('online:', ot.name, ot.status.detailed_state if ot.status else None)
except Exception as e: print('ot err', repr(e)[:300])
" 2>&1 | head -40

cd "$TESTBED_BOUNDARY" && python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
FQ='workspace.mlpab600b4f'
for t in ['airq0ecd46','airqtd0ecd46','airqpred0ecd46']:
    try:
        ti=w.tables.get(f'{FQ}.{t}')
        cols=[c.name for c in ti.columns]
        print('TABLE', t, 'cols', cols)
    except Exception as e:
        print('TABLE', t, 'ERR', str(e)[:150])
print('--- model versions ---')
try:
    mv=list(w.model_versions.list(f'{FQ}.airqmodel0ecd46'))
    for m in mv:
        print('model v', m.version, 'run', m.run_id)
except Exception as e:
    print('model ERR', str(e)[:200])
"
